@GameTestHolder("psychedelicrafttests") @PrefixGameTestTemplate(false)
public final class RiftGameTests {
 static final BlockPos P=new BlockPos(8,3,8);
 static void check(boolean value,String message){if(!value)throw new GameTestAssertException(message);}
 static void close(double actual,double expected,double tolerance,String message){check(Math.abs(actual-expected)<tolerance,message+": "+actual+" != "+expected);}
 static net.minecraftforge.common.util.FakePlayer player(GameTestHelper h){var p=FakePlayerFactory.get(h.getLevel(),new GameProfile(UUID.randomUUID(),"RiftTest"));p.setGameMode(GameType.SURVIVAL);p.getInventory().clearContent();p.setPos(h.absolutePos(P.offset(0,0,-3)).getCenter());return p;}
 static RiftJarBlockEntity jar(GameTestHelper h,float amount,float lid,boolean sucking){h.setBlock(P,PSBlocks.RIFT_JAR.get());var jar=(RiftJarBlockEntity)h.getLevel().getBlockEntity(h.absolutePos(P));var tag=new CompoundTag();tag.putFloat("currentRiftFraction",amount);tag.putFloat("fractionOpen",lid);tag.putBoolean("isOpening",lid>0);tag.putBoolean("suckingRifts",sucking);tag.putFloat("fractionHandleUp",sucking?0:1);jar.load(tag);return jar;}
 static void tick(RiftJarBlockEntity jar){RiftJarBlockEntity.tick(jar.getLevel(),jar.getBlockPos(),jar.getBlockState(),jar);}
 static RealityRiftEntity rift(GameTestHelper h,Vec3 pos,float size,boolean registered){var rift=PSEntities.REALITY_RIFT.get().create(h.getLevel());rift.setPos(pos);rift.setRiftSize(size);if(registered)h.getLevel().addFreshEntity(rift);return rift;}
 static Object cancelBlast(){var listener=new Object(){@SubscribeEvent public void cancel(ExplosionEvent.Start e){e.setCanceled(true);}};MinecraftForge.EVENT_BUS.register(listener);return listener;}
 @GameTest(template="world_fluid") public static void nativeJarShapeFacingAndCollisionMatchTheOriginalParts(GameTestHelper h){
  var block=PSBlocks.RIFT_JAR.get();var state=block.defaultBlockState();var pos=h.absolutePos(P);var shape=state.getShape(h.getLevel(),pos);check(!shape.isEmpty()&&shape.max(Direction.Axis.Y)==14/16D&&state.getPistonPushReaction()==PushReaction.DESTROY&&block.getRenderShape(state)==RenderShape.ENTITYBLOCK_ANIMATED,"native jar has four-part animated glass geometry and destroy piston reaction");check(state.rotate(Rotation.CLOCKWISE_90).getValue(RiftJarBlock.FACING)==Direction.EAST&&state.mirror(Mirror.LEFT_RIGHT).getValue(RiftJarBlock.FACING)==Direction.SOUTH,"native jar facing rotates and mirrors");check(shape.clip(pos.getCenter().add(0,6/16D-.5,-2),pos.getCenter().add(0,6/16D-.5,2),pos)!=null,"native ray enters the narrower neck");check(!Shapes.joinIsNotEmpty(shape,Shapes.box(.25,5/16D,.25,4.5/16D,7/16D,4.5/16D),BooleanOp.AND),"neck corners remain empty in native collision");h.succeed();
 }
 @GameTest(template="world_fluid") public static void jarFillTooltipBoundariesAndInvalidValuesFollowAcceptedData(GameTestHelper h){
  var item=PSItems.RIFT_JAR.get();float[] values={0,.25F,.55F,.75F,.9F,1.2F};String[] names={"empty","slightly_filled","half_filled","filled","over_filled","over_filled"};for(int i=0;i<values.length;i++){var stack=item.filled(values[i]);close(RiftJarItem.getRiftFraction(stack),values[i],1e-6,"finite fill is not truncated at the overload threshold");var lines=new ArrayList<Component>();item.appendHoverText(stack,h.getLevel(),lines,TooltipFlag.NORMAL);check(lines.get(lines.size()-1).getContents() instanceof net.minecraft.network.chat.contents.TranslatableContents text&&text.getKey().endsWith("."+names[i]),"native tooltip uses accepted fill boundary");}for(float bad:new float[]{-1,Float.NaN,Float.POSITIVE_INFINITY}){var stack=item.filled(0);stack.getOrCreateTag().putFloat(RiftJarItem.FILL,bad);check(RiftJarItem.getRiftFraction(stack)==0,"invalid saved fill is sanitized");}h.succeed();
 }
 @GameTest(template="world_fluid") public static void nativePlacementAndHarvestConserveNamedJarFillAndItemData(GameTestHelper h){
  var p=player(h);var level=h.getLevel();var pos=h.absolutePos(P);h.setBlock(P.below(),Blocks.STONE);var stack=PSItems.RIFT_JAR.get().filled(.73F);stack.setCount(2);stack.setHoverName(Component.literal("Named rift reserve"));stack.getOrCreateTag().putInt("custom",91);p.setItemInHand(InteractionHand.MAIN_HAND,stack);var hit=new BlockHitResult(pos.getCenter().add(0,-.5,0),Direction.UP,pos.below(),false);check(stack.useOn(new UseOnContext(p,InteractionHand.MAIN_HAND,hit)).consumesAction()&&stack.getCount()==1,"actual native BlockItem entry consumes one jar");var jar=(RiftJarBlockEntity)level.getBlockEntity(pos);check(jar!=null&&ItemStack.matches(jar.portableStack(),stack),"placed jar retains fraction/name/ordinary item fields");var expected=stack.copy();stack.getTag().putInt("custom",0);check(jar.portableStack().getTag().getInt("custom")==91,"placed item metadata is an independent snapshot");check(p.gameMode.destroyBlock(pos),"real native survival game mode destroys the jar");var drops=level.getEntitiesOfClass(ItemEntity.class,new AABB(pos).inflate(2),e->e.getItem().is(PSItems.RIFT_JAR.get()));check(drops.size()==1&&ItemStack.matches(expected,drops.get(0).getItem())&&level.getBlockEntity(pos)==null,"native harvest drops exactly one full named jar and removes its block entity");drops.forEach(Entity::discard);h.succeed();
 }
 @GameTest(template="world_fluid") public static void nativeUseTogglesLidAndModeWithoutConsumingHeldTools(GameTestHelper h){
  var jar=jar(h,.5F,0,true);var p=player(h);var held=new ItemStack(Items.STICK,3);p.setItemInHand(InteractionHand.MAIN_HAND,held);var pos=jar.getBlockPos();var block=PSBlocks.RIFT_JAR.get();var hit=new BlockHitResult(pos.getCenter(),Direction.NORTH,pos,false);check(block.use(jar.getBlockState(),h.getLevel(),pos,p,InteractionHand.MAIN_HAND,hit).consumesAction()&&jar.isOpening(),"normal native interaction opens the lid");tick(jar);close(jar.getLid(1),.02,1e-6,"lid advances by the accepted tick rate");p.setShiftKeyDown(true);block.use(jar.getBlockState(),h.getLevel(),pos,p,InteractionHand.MAIN_HAND,hit);tick(jar);check(!jar.isSucking()&&jar.isOpening()&&jar.getHandle(1)>0&&held.getCount()==3,"crouch interaction flips mode, animates handle and keeps the held tool");p.setShiftKeyDown(false);block.use(jar.getBlockState(),h.getLevel(),pos,p,InteractionHand.MAIN_HAND,hit);check(!jar.isOpening(),"second normal interaction closes the lid");h.succeed();
 }
 @GameTest(template="world_fluid") public static void nativeJarNbtKeepsAnimationAndPortableDataWithSafeMissingDefaults(GameTestHelper h){
  var jar=jar(h,.65F,.4F,false);var stack=PSItems.RIFT_JAR.get().filled(.65F);stack.setHoverName(Component.literal("Saved rift"));stack.getOrCreateTag().putInt("custom",7);jar.fromItem(stack);var saved=jar.saveWithFullMetadata();var restored=(RiftJarBlockEntity)BlockEntity.loadStatic(jar.getBlockPos(),jar.getBlockState(),saved);check(restored!=null&&restored.saveWithoutMetadata().equals(jar.saveWithoutMetadata())&&ItemStack.matches(restored.portableStack(),stack),"native registered block-entity load restores amount, mode, lid/handle and exact item data");var bare=new RiftJarBlockEntity(jar.getBlockPos(),jar.getBlockState());bare.load(new CompoundTag());check(bare.isSucking()&&!bare.isOpening()&&bare.getAmount()==0,"missing saved mode retains accepted collection default");var update=jar.getUpdatePacket();check(update!=null&&update.getTag().getFloat("currentRiftFraction")==.65F&&update.getTag().getBoolean("suckingRifts")==false,"native update packet contains complete current jar state");h.succeed();
 }
 @GameTest(template="world_fluid") public static void jarCollectionSharesItsRateAcrossNativeNearbyRifts(GameTestHelper h){
  var jar=jar(h,0,1,true);var pos=jar.getBlockPos().getCenter();var a=rift(h,pos.add(0,3,0),.4F,true);var b=rift(h,pos.add(1,4,0),.5F,true);tick(jar);close(jar.getAmount(),.001,1e-6,"one collection tick preserves total rate across two rifts");close(a.getRiftSize(),.3995,1e-6,"first source gives its equal share");close(b.getRiftSize(),.4995,1e-6,"second source gives its equal share");jar.toggleLid();for(int i=0;i<60;i++)tick(jar);float before=jar.getAmount();tick(jar);check(jar.getAmount()==before&&jar.getLid(1)==0,"fully closed jar stops transfer");a.discard();b.discard();h.succeed();
 }
 @GameTest(template="world_fluid") public static void jarExposureDrainsToAnExactSynchronizedEmptyAndResumesFromNbt(GameTestHelper h){
  var jar=jar(h,.0001F,1,false);tick(jar);check(jar.getAmount()==0&&jar.getUpdateTag().getFloat("currentRiftFraction")==0,"last partial discharge publishes exact empty instead of stale nonzero contents");var saved=jar.saveWithFullMetadata();var restored=(RiftJarBlockEntity)BlockEntity.loadStatic(jar.getBlockPos(),jar.getBlockState(),saved);restored.setLevel(h.getLevel());tick(restored);check(restored.getAmount()==0&&!restored.isSucking(),"empty discharge mode remains stable after a native save/load");h.succeed();
 }
 @GameTest(template="world_fluid") public static void overloadReleasesOneRiftAndNoDuplicateJarThroughNativeRemoval(GameTestHelper h){
  var jar=jar(h,1.1F,0,true);var cancel=cancelBlast();try{tick(jar);var pos=jar.getBlockPos();var rifts=h.getLevel().getEntitiesOfClass(RealityRiftEntity.class,new AABB(pos).inflate(5));check(rifts.size()==1&&Math.abs(rifts.get(0).getRiftSize()-1.1F)<1e-6&&rifts.get(0).position().equals(new Vec3(pos.getX()+1,pos.getY()+3.5,pos.getZ()+1)),"closed overfilled jar releases one native rift at the accepted position");check(h.getLevel().getBlockState(pos).isAir()&&h.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(pos).inflate(3),e->e.getItem().is(PSItems.RIFT_JAR.get())).isEmpty(),"overload removal produces no duplicate portable jar");rifts.forEach(Entity::discard);}finally{MinecraftForge.EVENT_BUS.unregister(cancel);}h.succeed();
 }
 @GameTest(template="world_fluid") public static void cancelledRiftSpawnKeepsOverloadedJarAndItsWholeReserve(GameTestHelper h){
  var jar=jar(h,1.1F,0,true);Object cancel=new Object(){@SubscribeEvent public void cancel(EntityJoinLevelEvent e){if(e.getEntity() instanceof RealityRiftEntity)e.setCanceled(true);}};MinecraftForge.EVENT_BUS.register(cancel);try{tick(jar);check(h.getLevel().getBlockEntity(jar.getBlockPos())==jar&&jar.getAmount()==1.1F&&!jar.isBroken(),"actual Forge spawn refusal preserves jar and all energy");}finally{MinecraftForge.EVENT_BUS.unregister(cancel);}h.succeed();
 }
 @GameTest(template="world_fluid") public static void overloadMergesIntoTheFirstNativeQueryResultWithoutDuplicatingEnergy(GameTestHelper h){
  var jar=jar(h,1.1F,0,true);var at=jar.getBlockPos().getCenter();var a=rift(h,at.add(-1,3,0),.4F,true);var b=rift(h,at.add(1,4,0),.5F,true);var order=h.getLevel().getEntitiesOfClass(RealityRiftEntity.class,new AABB(jar.getBlockPos().getX()-2,jar.getBlockPos().getY(),jar.getBlockPos().getZ()-2,jar.getBlockPos().getX()+3,jar.getBlockPos().getY()+10,jar.getBlockPos().getZ()+3));var first=order.get(0);float before=first.getRiftSize(),other=(first==a?b:a).getRiftSize();var cancel=cancelBlast();try{tick(jar);close(first.getRiftSize(),before+1.1F,1e-6,"overload follows native section iteration order");close((first==a?b:a).getRiftSize(),other,1e-6,"other nearby rift is unchanged");check(h.getLevel().getEntitiesOfClass(RealityRiftEntity.class,new AABB(jar.getBlockPos()).inflate(8)).size()==2,"merge creates no extra rift");}finally{MinecraftForge.EVENT_BUS.unregister(cancel);a.discard();b.discard();}h.succeed();
 }
 @GameTest(template="world_fluid") public static void riftSizeCriticalBleedAndNativeNbtRespectAcceptedBoundaries(GameTestHelper h){
  var rift=rift(h,h.absolutePos(P).getCenter(),.4F,false);close(rift.takeFromRift(.1F),.1,1e-6,"ordinary extraction returns exactly what was removed");close(rift.getRiftSize(),.3,1e-6,"ordinary source loses its extracted amount");rift.setRiftSize(4);check(rift.isCritical()&&rift.takeFromRift(.001F)==.2F&&rift.getRiftSize()==4,"critical rifts retain the accepted fixed unstable bleed without shrinking");rift.setRiftClosing(true);check(!rift.isCritical(),"closing rift no longer uses critical bleed");var tag=new CompoundTag();rift.save(tag);var restored=(RealityRiftEntity)EntityType.loadEntityRecursive(tag,h.getLevel(),java.util.function.Function.identity());check(restored!=null&&restored.getRiftSize()==4&&restored.isRiftClosing()&&restored.isNoGravity(),"native entity load retains registered identity and authoritative state");restored.setRiftSize(.6F);restored.load(new CompoundTag());close(restored.getRiftSize(),.6,1e-6,"absent NBT preserves initialized values");var explicit=new CompoundTag();explicit.putFloat("riftSize",0);explicit.putFloat("instability",Float.NaN);explicit.putBoolean("isRiftClosing",false);restored.load(explicit);check(restored.getRiftSize()==0&&restored.getInstability()==0&&!restored.isRiftClosing(),"explicit zero and invalid instability are handled separately from missing fields");h.succeed();
 }
 @GameTest(template="world_fluid") public static void passiveDecayAndKillUseAnAnimatedNativeEntityLifecycle(GameTestHelper h){
  var rift=rift(h,h.absolutePos(P).getCenter(),.6F,false);rift.setDeltaMovement(1,2,3);rift.tick();close(rift.getRiftSize(),.6F-1F/24000,1e-7,"ordinary rift uses accepted twenty-minute passive decay");check(rift.getDeltaMovement().equals(Vec3.ZERO)&&rift.getVisualSize(1)>0&&!rift.isRemoved(),"native tick keeps the rift stationary and animates visual size");for(int i=0;i<30;i++)rift.tick();rift.kill();check(rift.isRiftClosing()&&!rift.isRemoved(),"native kill starts closure instead of immediate removal");float before=rift.getRiftSize();rift.tick();close(rift.getRiftSize(),before-.05F,1e-6,"closure drains one twentieth per tick");int ticks=1;while(!rift.isRemoved()&&ticks++<200)rift.tick();check(rift.isRemoved()&&rift.getRiftSize()==0&&rift.getVisualSize(1)==0,"native lifecycle removes only after the visible tail reaches zero");h.succeed();
 }
 @GameTest(template="world_fluid",timeoutTicks=40) public static void nativePistonDestroysJarAndDropsItsFullContentsOnce(GameTestHelper h){
  var jar=jar(h,.55F,0,true);var pos=jar.getBlockPos();h.setBlock(P.west(),Blocks.PISTON.defaultBlockState().setValue(PistonBaseBlock.FACING,Direction.EAST));h.setBlock(P.west().below(),Blocks.REDSTONE_BLOCK);h.runAtTickTime(12,()->{var drops=h.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(pos).inflate(3),e->e.getItem().is(PSItems.RIFT_JAR.get()));check(!h.getLevel().getBlockState(pos).is(PSBlocks.RIFT_JAR.get())&&drops.stream().mapToInt(e->e.getItem().getCount()).sum()==1&&Math.abs(RiftJarItem.getRiftFraction(drops.get(0).getItem())-.55F)<1e-6,"real native piston destruction releases one filled jar");drops.forEach(Entity::discard);h.succeed();});
 }
 @GameTest(template="world_fluid",timeoutTicks=40) public static void nativeWeightedPressurePlateIgnoresRiftsAndCountsOrdinaryItems(GameTestHelper h){
  var pos=h.absolutePos(P);h.setBlock(P.below(),Blocks.STONE);h.setBlock(P,Blocks.LIGHT_WEIGHTED_PRESSURE_PLATE);var rift=rift(h,pos.getCenter().add(0,-.5,0),.2F,true);var block=Blocks.LIGHT_WEIGHTED_PRESSURE_PLATE;block.entityInside(h.getLevel().getBlockState(pos),h.getLevel(),pos,rift);check(h.getLevel().getBlockState(pos).getValue(WeightedPressurePlateBlock.POWER)==0,"native weighted plate honors rift trap immunity");var item=new ItemEntity(h.getLevel(),pos.getX()+.5,pos.getY(),pos.getZ()+.5,new ItemStack(Items.STONE));h.getLevel().addFreshEntity(item);block.entityInside(h.getLevel().getBlockState(pos),h.getLevel(),pos,item);check(h.getLevel().getBlockState(pos).getValue(WeightedPressurePlateBlock.POWER)==1,"native plate still counts one ordinary item with the rift present");item.discard();h.runAtTickTime(20,()->{check(h.getLevel().getBlockState(pos).getValue(WeightedPressurePlateBlock.POWER)==0,"native scheduled tick releases the plate while the rift remains");rift.discard();h.succeed();});
 }
 @GameTest(template="world_fluid") public static void nativeGlitchKeepsAirCollisionSupportLightAndInteractionSemantics(GameTestHelper h){
  var level=h.getLevel();var pos=h.absolutePos(P);var block=PSBlocks.GLITCH.get();h.setBlock(P,block);var state=level.getBlockState(pos);check(state.isAir()&&!state.canBeReplaced()&&state.getCollisionShape(level,pos).equals(Shapes.block())&&!state.canOcclude(),"native air flag remains independent of full collision and replacement rules");check(state.getLightEmission(level,pos)==0&&state.getLightBlock(level,pos)==1&&state.emissiveRendering(level,pos),"native glitch emits no world light, attenuates skylight and supplies emissive samples");check(state.isRedstoneConductor(level,pos)&&state.isFaceSturdy(level,pos,Direction.UP),"native glitch conducts redstone and supports attached blocks");var p=player(h);check(block.use(state,level,pos,p,InteractionHand.MAIN_HAND,new BlockHitResult(pos.getCenter(),Direction.NORTH,pos,false))==InteractionResult.PASS&&level.getBlockState(pos).is(Blocks.AIR),"native use clears glitch and passes to the held item");h.setBlock(P,block);block.entityInside(state,level,pos,p);check(level.getBlockState(pos).is(Blocks.AIR),"native entity overlap clears glitch");h.setBlock(P,block);var cow=EntityType.COW.create(level);block.fallOn(level,state,pos,cow,5);check(cow.getHealth()<10&&level.getBlockState(pos).is(Blocks.AIR),"native landing applies fall damage before clearing glitch");h.succeed();
 }
 @GameTest(template="world_fluid") public static void actualPlayerTickSettingControlsRandomSpawnWithoutKillingExistingRifts(GameTestHelper h){
  var p=player(h);p.setPos(h.absolutePos(P).getCenter().add(0,80,0));int original=PSConfig.RIFT_SPAWN_INTERVAL.get();var spawned=new ArrayList<RealityRiftEntity>();Object listener=new Object(){@SubscribeEvent public void joined(EntityJoinLevelEvent e){if(e.getEntity() instanceof RealityRiftEntity r)spawned.add(r);}};MinecraftForge.EVENT_BUS.register(listener);try{PSConfig.RIFT_SPAWN_INTERVAL.set(0);ivorius.psychedelicraft.entity.drug.DrugEvents.tick(new net.minecraftforge.event.TickEvent.PlayerTickEvent(net.minecraftforge.event.TickEvent.Phase.START,p));ivorius.psychedelicraft.entity.drug.DrugEvents.tick(new net.minecraftforge.event.TickEvent.PlayerTickEvent(net.minecraftforge.event.TickEvent.Phase.END,p));check(spawned.isEmpty(),"zero interval disables the actual player-tick spawn path");PSConfig.RIFT_SPAWN_INTERVAL.set(1);ivorius.psychedelicraft.entity.drug.DrugEvents.tick(new net.minecraftforge.event.TickEvent.PlayerTickEvent(net.minecraftforge.event.TickEvent.Phase.END,p));check(spawned.size()==1,"one-in-one actual player tick creates one native registered rift");var rift=spawned.get(0);var d=rift.position().subtract(p.position());check(Math.abs(d.x)<=50&&Math.abs(d.y)<=50&&Math.abs(d.z)<=50&&rift.getRiftSize()>=0&&rift.getRiftSize()<=1,"native random spawn keeps the accepted cube and triangular starting size");PSConfig.RIFT_SPAWN_INTERVAL.set(0);rift.tick();check(!rift.isRemoved(),"zero spawn setting does not delete existing rifts");}finally{PSConfig.RIFT_SPAWN_INTERVAL.set(original);MinecraftForge.EVENT_BUS.unregister(listener);spawned.forEach(Entity::discard);}h.succeed();
 }
 @GameTest(template="world_fluid",batch="rift_critical") public static void criticalRiftUsesNativeMagicDamageOnlyForNonPlayerTargets(GameTestHelper h){
  var at=h.absolutePos(P).getCenter();var cow=EntityType.COW.create(h.getLevel());cow.setNoAi(true);cow.setPos(at.add(1,0,0));h.getLevel().addFreshEntity(cow);var rift=rift(h,at,.6F,false);rift.tick();check(cow.getHealth()==10,"ordinary rift leaves non-player health intact");rift.setRiftSize(4);rift.tick();check(cow.getHealth()<10,"actual critical tick applies native magic damage to non-player targets");cow.discard();rift.discard();h.succeed();
 }
 @GameTest(template="world_fluid",batch="rift_critical") public static void criticalShellUsesNativeNegativeHeightAndDoublePrecisionBoundariesBeforeCollapse(GameTestHelper h){
  var level=h.getLevel();var center=new BlockPos(50000,0,50000);var rift=rift(h,center.getCenter(),3.25F,false);rift.setInstability(.8991F);var inner=center.offset(44,0,0);var shell=center.offset(45,0,0);var outside=center.offset(46,0,0);var negative=center.offset(0,-45,0);for(var pos:List.of(inner,shell,outside,negative)){level.getChunkAt(pos);level.setBlockAndUpdate(pos,Blocks.STONE.defaultBlockState());}rift.tick();check(rift.isRiftClosing()&&Math.abs(rift.getInstability()-.9001F)<1e-6&&rift.getRiftSize()==3.25F,"native critical tick crosses collapse threshold without early size decay");check(level.getBlockState(inner).is(Blocks.STONE)&&level.getBlockState(shell).is(PSBlocks.GLITCH.get())&&level.getBlockState(negative).is(PSBlocks.GLITCH.get())&&level.getBlockState(outside).is(Blocks.STONE),"only the double-precision advancing shell converts, including valid negative build height");float instability=rift.getInstability();rift.tick();close(rift.getRiftSize(),3.2,1e-6,"next native tick starts closing decay");check(rift.getInstability()==instability,"closing rift stops shell expansion");var saved=new CompoundTag();rift.save(saved);var restored=(RealityRiftEntity)EntityType.loadEntityRecursive(saved,level,java.util.function.Function.identity());check(restored.isRiftClosing()&&restored.getInstability()==instability&&restored.getRiftSize()==rift.getRiftSize(),"native save/reopen preserves the collapsed shell and authoritative state");int age=0;while(!restored.isRemoved()&&age++<200)restored.tick();check(restored.isRemoved()&&restored.getInstability()==instability,"saved collapse finishes without another corruption shell");h.succeed();
 }
}
